function addControllers(group) {
    const row_obj = {
        number: 0,
        min_pt: 1.0,
        electrons: true,
        muons: true,
        photons: false,
        jets: false,
        met: false,
        minetjets: 1.0,
        additional: false,
    };
    const gui = config_ispy.gui;
    const folder = getGUIFolder(gui, group);
    const names = getSceneObjects();
    if (group.includes("momentumCut")) {
        addController(folder, row_obj, "min_pt", 0, 100).onChange(() => {
            config_ispy.views.forEach((v) => {
                const physic_objs = [
                    ...config_ispy.scenes[v].getObjectByName("Physics").children,
                    ...config_ispy.scenes[v].getObjectByName("Tracking").children,
                ].filter((o) => o.visible && hasProperty(o.children[0].userData, "pt"));
                if (!physic_objs.length)
                    return;
                physic_objs.forEach((obj) => {
                    obj.children.forEach((o) => {
                        o.visible = o.userData.pt < row_obj.min_pt ? false : true;
                    });
                });
            });
        });
        addController(folder, row_obj, "minetjets", 0, 200).onChange(() => {
            config_ispy.views.forEach((v) => {
                const physic_objs = config_ispy.scenes[v].getObjectByName(names["Jets"]).children;
                if (!physic_objs.length)
                    return;
                physic_objs.forEach((o) => {
                    o.visible = o.userData.et < row_obj["minetjets"] ? false : true;
                });
            });
        });
    }
    if (group.includes("showFolder")) {
        const togglePhysicsObjects = (leptongroup, visibility) => {
            config_ispy.views.forEach((v) => {
                leptongroup.forEach((lepton) => {
                    const obj = config_ispy.scenes[v].getObjectByName(names[lepton]);
                    if (!obj)
                        return;
                    obj.visible = visibility;
                });
            });
        };
        const pt_controller = config_ispy.subfolders.controllers.filter((o) => o.property === "min_pt")[0];
        const jet_controller = config_ispy.subfolders.controllers.filter((o) => o.property === "minetjets")[0];
        addController(folder, row_obj, "electrons").onChange(function () {
            togglePhysicsObjects(["GsfElectrons"], Boolean(this.getValue()));
            pt_controller.setValue(pt_controller.getValue());
        });
        addController(folder, row_obj, "muons").onChange(function () {
            togglePhysicsObjects(["GlobalMuons", "TrackerMuons"], Boolean(this.getValue()));
            pt_controller.setValue(pt_controller.getValue());
        });
        addController(folder, row_obj, "photons").onChange(function () {
            togglePhysicsObjects(["Photons"], Boolean(this.getValue()));
        });
        addController(folder, row_obj, "jets").onChange(function () {
            togglePhysicsObjects(["Jets"], Boolean(this.getValue()));
            jet_controller.setValue(jet_controller.getValue());
        });
        addController(folder, row_obj, "met").onChange(function () {
            togglePhysicsObjects(["METs"], Boolean(this.getValue()));
        });
        addController(folder, row_obj, "additional").onChange(function () {
            togglePhysicsObjects(["Tracks"], Boolean(this.getValue()));
        });
    }
    folder.controllers.forEach((c) => {
        config_ispy.subfolders["controllers"].push(c);
    });
}
function addInfo(group) {
    const gui = config_ispy.gui;
    const folder = getGUIFolder(gui, group);
    const names = getSceneObjects();
    const currentEvent = getCurrentEvent();
    if (!currentEvent) {
        throw new Error("Current event is not defined.");
    }
    const met_pt = currentEvent.Collections[names["METs"]][0][1];
    const row_obj = {
        met: `${met_pt.toFixed(2)} GeV`,
        selectedTracks: "0",
        trackInfo: false,
    };
    addController(folder, row_obj, "met").onFinishChange(function () {
        this.setValue(this.initialValue);
    });
    addController(folder, row_obj, "selectedTracks").onFinishChange(function () {
        this.setValue(config_ispy.selected_objects.size);
    });
    addController(folder, row_obj, "trackInfo").onChange(function () {
        config_ispy.showTrackInfo = Boolean(this.getValue());
        removeExistingBubble();
    });
    folder.controllers.forEach((c) => {
        config_ispy.subfolders["info"].push(c);
    });
}

