function projectVector(v, s) {
    const size = Math.sqrt(v.x * v.x + v.y * v.y);
    if (s.y < 0.0)
        return new Vector3(0, -size, v.z);
    return new Vector3(0, size, v.z);
}
function projectPoint(v, s) {
    const size = Math.sqrt(v[0] * v[0] + v[1] * v[1]);
    if (s[1] < 0.0)
        return [0, -size, v[2]];
    return [0, size, v[2]];
}
function makeTrackPointsRZ(data, extra, assoc, style, selection) {
    if (!assoc) {
        throw "No association!";
    }
    let mi = 0;
    let pi;
    const positions = [];
    const lps = [];
    let ap, ai;
    for (let i = 0; i < data.length; i++) {
        positions[i] = [];
        ai = 20 + i * 21;
        if (ai >= assoc.length) {
            ai = assoc.length - 1;
        }
        ap = assoc[ai];
        lps.push(new Vector3(...extra[ap[1][1]][0]));
    }
    for (const entry of assoc) {
        mi = entry[0][1];
        pi = entry[1][1];
        positions[mi].push(projectVector(new Vector3(...extra[pi][0]), lps[mi]));
    }
    const tcolor = new Color(style.color);
    const transp = true;
    const lines = [];
    for (let k = 0; k < positions.length; k++) {
        const line = new Line(new three_module_BufferGeometry().setFromPoints(positions[k]), new LineBasicMaterial({
            color: tcolor,
            transparent: transp,
            opacity: style.opacity,
        }));
        line.userData.pt = data[k][selection.index];
        line.visible = data[k][selection.index] < selection.min_pt ? false : true;
        lines.push(line);
    }
    return lines;
}
