function onMouseMove(e) {
    e.preventDefault();
    const display = utils_getHTMLObject("js-display");
    const w = display.clientWidth;
    const h = display.clientHeight;
    const doc = document.documentElement;
    const left = (window.pageXOffset || doc.scrollLeft) - (doc.clientLeft || 0);
    const top = (window.pageYOffset || doc.scrollTop) - (doc.clientTop || 0);
    const offsetX = display.getBoundingClientRect().left + window.pageXOffset - left;
    const offsetY = display.getBoundingClientRect().top + window.pageYOffset - top;
    const pointer = new Vector2();
    pointer.x = ((e.clientX - offsetX) / w) * 2 - 1;
    pointer.y = -((e.clientY - offsetY) / h) * 2 + 1;
    config_ispy.raycaster.setFromCamera(pointer, config_ispy.camera);
    const physicsObject = config_ispy.scene?.getObjectByName("Physics");
    const intersects = physicsObject ? config_ispy.raycaster.intersectObject(physicsObject, true) : [];
    if (config_ispy.intersected) {
        document.body.style.cursor = "auto";
        if (!config_ispy.intersected.selected) {
            const original_color = new Color(event_description[config_ispy.current_view][config_ispy.intersected.name].style.color);
            config_ispy.intersected.material.color = original_color;
        }
        else {
            config_ispy.intersected.material.color.setHex(0xcccccc);
        }
        config_ispy.intersected = null;
    }
    if (intersects.length > 0) {
        const res = intersects.filter((res) => {
            return res?.object;
        })[0];
        if (res?.object) {
            config_ispy.intersected = res.object;
            document.body.style.cursor = "pointer";
            config_ispy.intersected.material.color.setHex(0xcccccc);
        }
        if (config_ispy.showTrackInfo) {
            const intersectedObject = intersects[0].object;
            showTrackInfoBubble(intersectedObject, pointer);
        }
        else {
            removeExistingBubble();
        }
    }
}
