    config_ispy.stats.update();
    config_ispy.controls.update();
    config_ispy.inset_camera.position.subVectors(config_ispy.camera.position, config_ispy.controls.target);
    config_ispy.inset_camera.up = config_ispy.camera.up;
    config_ispy.inset_camera.quaternion.copy(config_ispy.camera.quaternion);
    config_ispy.inset_camera.position.setLength(10);
    config_ispy.inset_camera.lookAt(config_ispy.inset_scene.position);
    for (const text of ["xtext", "ytext", "ztext"]) {
        const textObj = config_ispy.inset_scene.getObjectByName(text);
        if (textObj) {
            textObj.quaternion.copy(config_ispy.inset_camera.quaternion);
        }
    }
    render();
    if (config_ispy.animating) {
        update();
    }
    if (config_ispy.autoRotating) {
        const speed = Date.now() * 0.0005;
        config_ispy.camera.position.x = Math.cos(speed) * 10;
        config_ispy.camera.position.z = Math.sin(speed) * 10;
    }
