function getTutorialSteps(tutorial, lang) {
    if (!["basics", "controls", "analysis"].includes(tutorial)) {
        console.error("Invalid tutorial key:", tutorial);
        throw new Error("Invalid tutorial key");
    }
    const key = tutorial;
    const availableLanguages = {
        en: enStepTexts[key],
        de: deStepTexts[key],
    };
    if (!availableLanguages[lang]) {
        window.alert(`No tutorial translation for language ${lang}, falling back to English`);
    }
    const textSteps = availableLanguages[lang] || availableLanguages["en"];
    return availableTutorials[key](textSteps);
}


;// ./js/tutorial.js



function startTutorial(key) {
    const tutorialSteps = getTutorialSteps(key, config_ispy.lang);
    const driverObj = Ae({
        animate: false,
        showProgress: true,
        allowClose: false,
        overlayOpacity: 0.4,
        showButtons: ["next", "previous", "close"],
        nextBtnText: "<i class='fa fa-arrow-right'></i>",
        prevBtnText: "<i class='fa fa-arrow-left'></i>",
        doneBtnText: "<i class='fa fa-check'></i>",
        steps: tutorialSteps,
        disableActiveInteraction: true,
        allowKeyboardControl: false,
        onDestroyed: () => {
            window.location.reload();
        },
    });
    driverObj.drive();
}

