function exportString(output, filename) {
    const blob = new Blob([output], { type: "text/plain" });
    const objectURL = URL.createObjectURL(blob);
    console.log(filename);
    downloadData(objectURL, filename);
}
function exportArrayBuffer(output, filename) {
    const blob = new Blob([output], { type: "application/octect-stream" });
    const objectURL = URL.createObjectURL(blob);
    console.log(filename);
    downloadData(objectURL, filename);
}
function exportGLTF_binary() {
    exportGLTF(true);
}
function exportGLTF_text() {
    exportGLTF(false);
}
function exportGLTF(binary) {
    utils_assertDefined(config_ispy.scene);
    const exporter = new GLTFExporter();
    const options = {
        binary: binary,
    };
    config_ispy.scene.children.forEach((c) => {
        if (c.children.length > 0 && c.name !== "Lights") {
            c.children.forEach((o) => {
                if (o.visible) {
                    exporter.parse(o, (result) => {
                        if (result instanceof ArrayBuffer) {
                            exportArrayBuffer(result, `${o.name}.glb`);
                        }
                        else {
                            const output = JSON.stringify(result, null, 2);
                            exportString(output, `${o.name}.gltf`);
                        }
                    }, options);
                }
            });
        }
    });
}
function exportOBJ() {
    utils_assertDefined(config_ispy.scene);
    const exporter = new OBJExporter();
    config_ispy.scene.children.forEach((c) => {
        if (c.children.length > 0 && c.name !== "Lights") {
            c.children.forEach((o) => {
                if (o.visible) {
                    exportString(exporter.parse(o), `${o.name}.obj`);
                }
            });
        }
    });
}
function showMass() {
    let mass = 0;
    let sumE = 0;
    let sumPx = 0;
    let sumPy = 0;
    let sumPz = 0;
    config_ispy.selected_objects.forEach((o, _key) => {
        sumE += o.fourVector.E;
        sumPx += o.fourVector.px;
        sumPy += o.fourVector.py;
        sumPz += o.fourVector.pz;
        if (o.ptype === "Electron") {
            o.material.color.setHex(0x19ff19);
        }
        if (o.ptype === "Muon") {
            o.material.color.setHex(0xff0000);
        }
        o.selected = false;
    });
    mass = sumE * sumE;
    mass -= sumPx * sumPx + sumPy * sumPy + sumPz * sumPz;
    mass = Math.sqrt(mass);
    utils_getHTMLObject("js-invariant-mass").innerHTML = mass.toFixed(2);
    showDialog("invariant-mass-modal");
    config_ispy.selected_objects.clear();
    config_ispy.subfolders["info"][1].setValue(0);
}
