function switchMain(view) {
    const mainMap = {
        about: utils_getHTMLObject("js-about"),
        display: utils_getHTMLObject("js-display"),
        help: utils_getHTMLObject("js-help"),
    };
    const btnMap = {
        about: utils_getHTMLObject("js-about-btn"),
        display: utils_getHTMLObject("js-event-display"),
        help: utils_getHTMLObject("js-help-btn"),
    };
    for (const key in mainMap) {
        if (key === view) {
            mainMap[key].hidden = false;
            btnMap[key].classList.add("active");
        }
        else {
            mainMap[key].hidden = true;
            btnMap[key].classList.remove("active");
        }
    }
    document.querySelectorAll(".guide-container").forEach((el) => {
        el.removeAttribute("style");
    });
    if (view === "display") {
        showToolbarButtons();
        showEventName();
    }
    else {
        hideToolbarButtons();
        hideEventName();
    }
}
