function setupKeyboardListeners() {
    document.addEventListener("keydown", (e) => {
        if (e.key === "E") {
            exportScene();
        }
        if (e.key === "ArrowUp" && e.shiftKey) {
            zoomIn();
        }
        if (e.key === "ArrowDown" && e.shiftKey) {
            zoomOut();
        }
        if (e.key === "ArrowRight") {
            nextEvent();
        }
        if (e.key === "ArrowLeft") {
            prevEvent();
        }
        if (e.key === "A") {
            toggleAnimation();
        }
        if (e.key === "m") {
            showMass();
        }
    });
}

